package dev.warden.dashboard;

/** Connection editor. A key field is rendered only when the OS vault probe succeeded. */
public final class ConnectionSettingsUi {
    private ConnectionSettingsUi() {}

    public static String html() { return html(false); }

    public static String html(boolean osStore) {
        String option = osStore ? "<option value=\"os\">Ключ в хранилище Windows</option>" : "";
        String field = osStore
                ? "<label id=\"connection-secret-field\" for=\"connection-secret\" hidden>Ключ для хранилища Windows<input id=\"connection-secret\" name=\"secret\" type=\"password\" maxlength=\"2048\" autocomplete=\"off\" spellcheck=\"false\"><span class=\"muted\">Значение записывается один раз в Credential Manager и не попадает в файл подключения. Панель не возвращает его. Поле можно оставить пустым.</span></label>"
                : "";
        String note = osStore
                ? "<p class=\"muted\">Если выбрано хранилище Windows, введённый ключ уходит отдельным запросом и сразу стирается из формы. Сохранение по-прежнему не добавляет профиль в состав ролей.</p>"
                : "";
        return HTML.replace("{{OS_STORE_OPTION}}", option)
                .replace("{{OS_STORE_FIELD}}", field)
                .replace("{{OS_STORE_NOTE}}", note);
    }

    private static final String HTML = """
            <section id="connection-editor" aria-labelledby="connection-editor-title" data-token="{{SETTINGS_TOKEN}}">
            <style>
            #connection-editor .connection-toolbar{display:flex;gap:8px;align-items:center;flex-wrap:wrap}
            #connection-editor .connection-actions{display:flex;gap:6px;flex-wrap:nowrap}
            #connection-editor .connection-actions button{white-space:nowrap}
            #connection-editor button:disabled{cursor:wait;opacity:.55}
            #connection-editor form{margin:16px 0;padding:20px;border:1px solid #405363;border-radius:12px;background:#151f28}
            #connection-editor fieldset{border:0;margin:0;padding:0}
            #connection-editor .connection-fields{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:16px}
            #connection-editor label{display:flex;flex-direction:column;gap:6px}
            #connection-editor input,#connection-editor select{box-sizing:border-box;width:100%;min-width:0;background:#19232c;border:1px solid #405363;border-radius:6px;padding:8px 12px;color:inherit;font:inherit}
            #connection-editor .connection-checkbox{display:flex;flex-direction:row;gap:8px;align-items:center;margin:16px 0}
            #connection-editor input[type=checkbox]{width:auto;min-width:0;margin:0}
            #connection-editor input:read-only{color:#9caebd}
            #connection-editor .connection-address{white-space:nowrap}
            #connection-editor .connection-feedback{min-height:1.5em;white-space:pre-wrap;overflow-wrap:anywhere}
            #connection-editor .connection-good{color:#9ee9c6}
            #connection-editor .connection-problems{white-space:pre-wrap}
            #connection-editor [hidden]{display:none!important}
            </style>
            <h2 id="connection-editor-title">Подключения</h2>
            <p class="muted">API-подключение хранит адрес сервиса и ссылку на переменную окружения. Значение ключа сюда не вводится, пока хранилище ОС недоступно. Наличие ключа не подтверждает авторизацию или доступ к модели. Проверка подключения не вызывает модель и не подтверждает её пригодность к роли.</p>
            {{OS_STORE_NOTE}}
            <div class="connection-toolbar"><button id="connection-add" type="button">Добавить подключение</button><button id="connection-reload" type="button">Перечитать подключения</button></div>
            <p id="connection-feedback" class="connection-feedback muted" role="status" aria-live="polite"></p>
            <p id="connection-problems" class="connection-problems bad" hidden></p>
            <div class="scroll"><table><thead><tr><th>Подключение · сервис</th><th>Адрес</th><th>Источник ключа</th><th>Состояние</th><th>Включено</th><th>Действия</th></tr></thead><tbody id="connection-editor-rows"></tbody></table><div id="connection-editor-empty" class="empty" hidden>Подключений пока нет. Добавьте сервис и укажите имя переменной окружения с его ключом.</div></div>
            <form id="connection-editor-form" hidden>
            <fieldset id="connection-editor-fields">
            <h3 id="connection-form-title">Новое подключение</h3>
            <div class="connection-fields">
            <label for="connection-id">Имя подключения<input id="connection-id" name="id" type="text" required maxlength="64" pattern="[a-z][a-z0-9_\\-]{0,63}" autocomplete="off" spellcheck="false"><span class="muted">Латинские строчные буквы, цифры, дефис и подчёркивание.</span></label>
            <label for="connection-provider">Сервис<select id="connection-provider" name="provider"><option value="openrouter">OpenRouter</option><option value="gonkarouter">GonkaRouter</option><option value="joingonka">JoinGonka Gateway</option><option value="custom">Совместимый API</option></select></label>
            <label for="connection-base-url">Адрес API<input id="connection-base-url" name="base_url" type="url" required autocomplete="off" spellcheck="false"><span class="muted">HTTPS для удалённого сервиса; HTTP допускается только для локального адреса.</span></label>
            <label for="connection-auth">Авторизация<select id="connection-auth" name="auth"><option value="env">Ключ из переменной окружения</option><option value="none">Без ключа — локальный API</option>{{OS_STORE_OPTION}}</select></label>
            <label id="connection-env-field" for="connection-env">Переменная окружения с ключом<input id="connection-env" name="env" type="text" maxlength="128" pattern="[A-Za-z_][A-Za-z0-9_]{0,127}" autocomplete="off" spellcheck="false"><span class="muted">Например, OPENROUTER_API_KEY. Укажите имя переменной, не значение ключа.</span></label>
            {{OS_STORE_FIELD}}
            </div>
            <label class="connection-checkbox" for="connection-enabled"><input id="connection-enabled" name="enabled" type="checkbox" checked>Подключение включено</label>
            <p class="muted">Сохранение не добавляет модель в состав ролей. Переменная должна быть задана в окружении процесса Warden; форма не изменяет окружение или авторизацию CLI.</p>
            <div class="connection-toolbar"><button id="connection-save" type="submit">Добавить</button><button id="connection-cancel" type="button">Отменить</button></div>
            </fieldset></form>
            <p class="muted">Прямые API-профили работают с текстом. Для кодинга доступен OpenCode после отдельной проверки профиля. CLI-подписки используют собственную авторизацию. Удаление подключения не отзывает ключ на сервисе.</p>
            <details><summary>Настройка через CLI</summary><p><code>warden connections add openrouter-personal --provider openrouter --env OPENROUTER_API_KEY</code></p><p class="muted">В настройках сохранится ссылка <code>env:OPENROUTER_API_KEY</code>. Значение ключа задаётся отдельно в окружении процесса Warden.</p></details>
            <script>
            (()=>{
            const byId=id=>document.getElementById(id),section=byId('connection-editor'),form=byId('connection-editor-form');
            const processToken=section.dataset.token,fields=byId('connection-editor-fields'),body=byId('connection-editor-rows');
            const idInput=byId('connection-id'),providerInput=byId('connection-provider'),baseInput=byId('connection-base-url'),authInput=byId('connection-auth'),envInput=byId('connection-env'),secretInput=byId('connection-secret'),enabledInput=byId('connection-enabled');
            const defaults={openrouter:{url:'https://openrouter.ai/api/v1',env:'OPENROUTER_API_KEY'},gonkarouter:{url:'https://api.gonkarouter.io/v1',env:'GONKAROUTER_API_KEY'},joingonka:{url:'https://gate.joingonka.ai/v1',env:'JOINGONKA_API_KEY'}};
            let pending=false,editing=null;
            const messages={connection_revision_conflict:'Подключение изменено в другом окне. Черновик сохранён. Перечитайте список и нажмите «Изменить» у этой строки, чтобы принять новую версию, не стирая поля.',connection_in_use:'Подключение используется профилем или его ссылки пока нельзя проверить. Сначала измените профиль.',connection_exists:'Подключение с таким именем уже существует. Выберите другое имя.',connection_not_found:'Подключение больше не найдено. Перечитайте список.',connection_layout_unsupported:'Файл имеет неподдерживаемое оформление YAML. Изменения не записаны; отредактируйте файл вручную.',connection_store_unavailable:'Файлы подключений недоступны. Проверьте каталог настроек Warden.',role_api_key_missing:'Ключ отсутствует или недоступен в окружении процесса Warden. Проверьте указанную переменную.',role_api_auth_invalid:'Сервис отклонил ключ. Проверьте авторизацию этого подключения. Модель не вызывалась.',role_api_connection_disabled:'Подключение отключено. Включите его перед проверкой.',role_api_rate_limited:'Сервис временно ограничил запросы. Повторите проверку позже; модель не вызывалась.',role_api_credits_exhausted:'Сервис сообщил об исчерпании средств или лимита ключа. Проверка подключения не завершена; модель не вызывалась.',role_api_budget_exhausted:'Сервис сообщил об исчерпании бюджета. Проверьте ограничения аккаунта или ключа; модель не вызывалась.',role_api_access_denied:'Сервис отказал в доступе. Проверьте разрешения аккаунта и ключа; модель не вызывалась.',role_api_network_error:'Не удалось связаться с API сервиса. Проверьте адрес и сетевое подключение; модель не вызывалась.',role_api_provider_error:'Сервис вернул ошибку. Повторите проверку позже; модель не вызывалась.',role_api_timeout:'Сервис не ответил вовремя. Проверка авторизации не завершена; модель не вызывалась.',credential_rejected:'Ключ отклонён и не записан. Нужны печатаемые символы без пробела.',credential_store_not_selected:'Это подключение не использует хранилище ОС. Ключ не записан.',credential_store_unavailable:'Хранилище ОС недоступно. Ключ не записан и не заменён другим источником.'};
            function feedback(text,error=false){const target=byId('connection-feedback');target.textContent=text;target.className='connection-feedback '+(error?'bad':'connection-good')}
            function setPending(value){pending=value;fields.disabled=value;byId('connection-add').disabled=value;byId('connection-reload').disabled=value;body.querySelectorAll('button').forEach(button=>button.disabled=value)}
            function cell(row,value,className){const target=document.createElement('td');target.textContent=value??'—';if(className)target.className=className;row.append(target);return target}
            function button(label,handler){const target=document.createElement('button');target.type='button';target.textContent=label;target.disabled=pending;target.addEventListener('click',handler);return target}
            function authState(auth){switch(auth?.state){case 'not_required':return 'ключ не требуется';case 'ready':return 'ключ задан · авторизация не проверена';case 'invalid':return 'неверный формат ключа';case 'unavailable':return 'источник ключа недоступен';case 'disabled':return 'отключено';default:return 'ключ не задан'}}
            function render(rows){body.replaceChildren();for(const connection of rows){const row=document.createElement('tr');cell(row,connection.id+' · '+connection.provider);cell(row,connection.base_url,'connection-address');cell(row,connection.auth?.source??'none');cell(row,authState(connection.auth));cell(row,connection.enabled?'да':'нет');const actions=cell(row,'');actions.className='connection-actions';actions.append(button('Изменить',()=>edit(connection)),button('Проверить',()=>request('check',{id:connection.id,revision:connection.revision})),button(connection.enabled?'Отключить':'Включить',()=>request(connection.enabled?'disable':'enable',{id:connection.id,revision:connection.revision})),button('Удалить',()=>{if(!window.confirm('Удалить подключение '+connection.id+'? Ключ на сервисе не отзывается.'))return;request('remove',{id:connection.id,revision:connection.revision})}));body.append(row)}byId('connection-editor-empty').hidden=rows.length>0}
            async function readList(){const response=await fetch('/api/connections',{cache:'no-store',credentials:'same-origin'});let data;try{data=await response.json()}catch(error){throw {status:response.status,code:'connection_store_unavailable'}}if(!response.ok||!Array.isArray(data.connections))throw {status:response.status,code:data.code??'connection_store_unavailable',message:data.message};render(data.connections);const problems=Object.entries(data.problems??{}).map(([name,message])=>name+': '+message);byId('connection-problems').textContent=problems.join(String.fromCharCode(10));byId('connection-problems').hidden=problems.length===0}
            function syncAuth(){const mode=authInput.value;const env=mode==='env';byId('connection-env-field').hidden=!env;envInput.disabled=!env;envInput.required=env;const secretField=byId('connection-secret-field');if(secretField){secretField.hidden=mode!=='os';if(secretInput){secretInput.disabled=mode!=='os';if(mode!=='os')secretInput.value=''}}}
            function syncProvider(fill){const preset=defaults[providerInput.value];const leavingPreset=Object.values(defaults).some(value=>value.url===baseInput.value);baseInput.readOnly=Boolean(preset);authInput.querySelector('option[value=none]').disabled=Boolean(preset);if(preset){if(authInput.value==='none'||(fill&&authInput.value!=='os'))authInput.value='env';if(fill){baseInput.value=preset.url;if(!envInput.value||Object.values(defaults).some(value=>value.env===envInput.value))envInput.value=preset.env}}else if(fill&&leavingPreset)baseInput.value='';syncAuth()}
            function closeForm(){if(secretInput)secretInput.value='';form.hidden=true;editing=null;idInput.readOnly=false}
            function begin(){if(pending)return;editing=null;form.reset();idInput.readOnly=false;providerInput.value='openrouter';envInput.value='OPENROUTER_API_KEY';syncProvider(true);byId('connection-form-title').textContent='Новое подключение';byId('connection-save').textContent='Добавить';form.hidden=false;feedback('Укажите сервис и имя переменной окружения с ключом.');idInput.focus()}
            function edit(connection){if(pending)return;const source=connection.auth?.source??'none';if(source.startsWith('os-store:')&&!authInput.querySelector('option[value=os]')){feedback('Хранилище ОС сейчас недоступно. Источник ключа не изменён.',true);return}const same=editing&&editing.id===connection.id;editing={id:connection.id,revision:connection.revision};if(!same){idInput.value=connection.id;idInput.readOnly=true;providerInput.value=connection.provider;baseInput.value=connection.base_url;authInput.value=source.startsWith('env:')?'env':source.startsWith('os-store:')?'os':'none';envInput.value=source.startsWith('env:')?source.slice(4):'';if(secretInput)secretInput.value='';enabledInput.checked=Boolean(connection.enabled)}else idInput.readOnly=true;syncProvider(false);byId('connection-form-title').textContent='Изменить подключение '+connection.id;byId('connection-save').textContent='Сохранить';form.hidden=false;feedback(same?'Черновик сохранён. Сохранение запишет его в версию, которая сейчас показана в списке.':'Изменения будут сохранены только для открытой версии подключения.');if(!same)baseInput.focus()}
            function errorText(error){if(messages[error?.code])return messages[error.code];if(error?.code?.startsWith('role_api_'))return 'Сервис не подтвердил подключение. Проверка не завершена; модель не вызывалась.';if(error?.code==='connection_invalid')return typeof error.message==='string'?error.message:'Проверьте имя, адрес API и источник авторизации.';if(error?.status===409)return 'Настройки изменились или операция недоступна. Черновик сохранён; перечитайте список.';if(typeof error?.status==='number')return typeof error.message==='string'&&error.message?error.message:'Панель не выполнила операцию.';return 'Нет связи с панелью. Изменения не подтверждены.'}
            function checkResult(data){if(data.auth_verified===true)return 'Авторизация подтверждена сервисом. Проверка не вызывает модель и не проверяет инструменты.';if(data.code==='no_auth_required')return 'Для этого локального адреса ключ не требуется. Запрос к модели не выполнялся.';return 'Источник ключа задан локально. Авторизация сервисом не подтверждена; запрос к модели не выполнялся.'}
            async function request(operation,payload,fromForm=false){if(pending)return null;setPending(true);feedback(operation==='check'?'Проверяю подключение без вызова модели…':'Сохраняю изменение…');try{const response=await fetch('/api/connections/'+operation,{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-Warden-Token':processToken},body:JSON.stringify(payload)});let data;try{data=await response.json()}catch(error){throw {status:response.status}}if(!response.ok||data.ok!==true)throw {status:response.status,code:data.code,message:data.message};if(operation==='check'){feedback(checkResult(data));return data}if(operation==='auth-set'){const stored='Ключ записан в хранилище Windows. Файл подключения его не содержит. Состав ролей не менялся.';feedback(stored);try{await readList()}catch(error){feedback(stored+' Список не обновился — перечитайте подключения.',true)}return data}if(operation==='auth-remove'){feedback('Локальная запись хранилища удалена. Ключ на сервисе не отозван.');try{await readList()}catch(error){feedback('Локальная запись хранилища удалена. Список не обновился — перечитайте подключения.',true)}return data}if(fromForm||(operation==='remove'&&editing?.id===payload.id))closeForm();document.dispatchEvent(new CustomEvent('warden:connections-changed'));const saved=operation==='remove'?'Подключение удалено. Ключ на сервисе не отозван.':'Подключение сохранено. Состав ролей не менялся.';feedback(saved);try{await readList()}catch(error){feedback(saved+' Список не обновился — перечитайте подключения.',true)}return data}catch(error){feedback(errorText(error),true);return null}finally{setPending(false)}}
            form.addEventListener('submit',async event=>{event.preventDefault();if(pending||!form.reportValidity())return;const mode=authInput.value;const id=idInput.value.trim();let secret='';if(secretInput&&mode==='os'){secret=secretInput.value;secretInput.value=''}const payload={id,provider:providerInput.value,base_url:baseInput.value.trim(),credential_ref:mode==='none'?null:mode==='os'?'os-store:warden/'+id:'env:'+envInput.value.trim(),enabled:enabledInput.checked};if(editing){payload.id=editing.id;payload.revision=editing.revision;if(mode==='os')payload.credential_ref='os-store:warden/'+payload.id}const saved=await request(editing?'update':'add',payload,true);if(saved&&secret){const revision=saved.connection&&saved.connection.revision;if(typeof revision!=='string'||!await request('auth-set',{id:payload.id,revision,secret},false))feedback('Ссылка сохранена, но ключ не записан в хранилище. Введите его ещё раз. Панель его не хранит.',true)}secret=''});
            byId('connection-add').addEventListener('click',begin);byId('connection-cancel').addEventListener('click',()=>{closeForm();feedback('Редактирование отменено.')});providerInput.addEventListener('change',()=>syncProvider(true));authInput.addEventListener('change',syncAuth);
            byId('connection-reload').addEventListener('click',async()=>{if(pending)return;setPending(true);try{await readList();feedback(editing?'Список обновлён. Черновик сохранён. Нажмите «Изменить» у этой строки, чтобы принять показанную версию, и затем сохраните.':'Подключения перечитаны.')}catch(error){feedback(errorText(error),true)}finally{setPending(false)}});
            setPending(true);readList().then(()=>feedback('Подключения прочитаны.')).catch(error=>feedback(errorText(error),true)).finally(()=>setPending(false));
            })();
            </script></section>
            """;
}
